"""Build the first three Turkey chapters from cited editorial annotations and existing CShapes snapshots.
No downloads. Facts are paraphrased by Orbis; no source prose/images are redistributed.
CShapes subset and topology derivation retain CC BY-NC-SA 4.0 and remain optional story data.
Run python tools/build/turkey_first_release.py, then review unlisted stories before registration.
"""
from pathlib import Path
import copy,json
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'data/history/turkey';OUT.mkdir(parents=True,exist_ok=True)
def write(path,d):
 path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(d,ensure_ascii=False,indent=1)+'\n',encoding='utf-8')
TBMM='https://www.tbmm.gov.tr/history/'
CONSTITUTION='https://en.wikisource.org/wiki/Ottoman_constitution_of_1876'
MEB='https://meb.gov.tr/ataturk/Hayati/Kronoloji'
NAM='https://www.nam.ac.uk/explore/gallipoli'
USHMM='https://encyclopedia.ushmm.org/content/en/article/the-armenian-genocide-1915-16-overview'
TREATY='https://www.mfa.gov.tr/lausanne-peace-treaty-part-i_-political-clauses.en.mfa'
EXCHANGE='https://www.mfa.gov.tr/lausanne-peace-treaty-vi_-convention-concerning-the-exchange-of-greek-and-turkish-populations-signed-at-lausanne_.en.mfa'
# Copy only referenced arcs, preserving quantization and ring direction. All input transforms match.
arcs=[];geoms=[];transform=None
snapdates={1886:'1886-01-01',1900:'1900-07-01',1914:'1914-07-01',1920:'1920-01-01',1925:'1925-01-01'}
for y,to in [(1886,1900),(1900,1914),(1914,1920),(1920,1925),(1925,1938)]:
 src=json.loads((ROOT/f'data/history/borders-{y}.json').read_text(encoding='utf-8'))
 if transform is None:transform=src['transform']
 assert transform==src['transform']
 selected=[g for g in next(iter(src['objects'].values()))['geometries'] if g['properties']['id'] in ['OTT','TUR']]
 assert len(selected)==1
 g=copy.deepcopy(selected[0]); refs={}
 def remap(x):
  if isinstance(x,list):return [remap(v) for v in x]
  i=x if x>=0 else ~x
  if i not in refs:refs[i]=len(arcs);arcs.append(src['arcs'][i])
  return refs[i] if x>=0 else ~refs[i]
 g['arcs']=remap(g['arcs']);old=g['properties'];g['properties']={'name':('Ottoman Empire' if old['id']=='OTT' else 'Turkey')+' · '+snapdates[y],'from':y,'to':to,'group':'ottoman' if old['id']=='OTT' else 'republic','at':[old['lx'],old['ly']],'note':'CShapes 2.0 selected snapshot '+snapdates[y]+'. Display holds this observation until the next selected snapshot; not evidence of daily control.','sourceDate':snapdates[y]};geoms.append(g)
write(OUT/'snapshots.json',{'source':'cshapes','asOf':'CShapes 2.0','retrieved':'2026-10-14','licence':'CC BY-NC-SA 4.0','note':'Orbis subset of existing simplified CShapes snapshots; non-commercial/share-alike. Selected observation dates are exact in feature properties. from/to define display steps, not validity dates for all intermediate borders. Legal state borders omit small changes and temporary wartime occupations; not a front-line or de facto control dataset. Selected independent state only: dependencies, spheres of influence and occupation are not represented. The 1925 source name was Turkey (Ottoman Empire); the display label is corrected to Turkey.','groups':{'ottoman':{'label':'Ottoman state (dated snapshot)','color':'c2'},'republic':{'label':'Turkey (dated snapshot)','color':'c4'}},'topology':{'type':'Topology','transform':transform,'objects':{'shapes':{'type':'GeometryCollection','geometries':geoms}},'arcs':arcs}})
AT={'istanbul':[28.98,41.01],'ankara':[32.85,39.93],'samsun':[36.33,41.29],'thessaloniki':[22.94,40.64],'gallipoli':[26.4,40.25],'kharput':[39.22,38.7],'syria':[40.14,35.34],'lausanne':[6.63,46.52],'izmir':[27.14,38.42],'sakarya':[31.8,39.5],'dumlupinar':[29.98,38.85]}
def item(title,date,place,text,url,kind='politics'):
 return {'title':title,'date':date,'at':AT[place],'text':text,'source':url,'url':url,'kind':kind}
reform=[item('Constitution promulgated',18761223,'istanbul','The sultan promulgated the Kanun-i Esasi on 23 December 1876.',TBMM),item('First parliament opens',18770319,'istanbul','The first Ottoman parliament opened on 19 March 1877.',TBMM),item('Parliament suspended',18780214,'istanbul','Parliament was adjourned indefinitely on 14 February 1878.',TBMM),item('Constitution restored',19080723,'thessaloniki','The constitution was restored in July 1908 after a revolt by officers and troops in Macedonia. This marker locates that regional context, not one exact meeting.',TBMM)]
war=[item('Gallipoli landings',19150425,'gallipoli','British Empire and French troops landed on the Ottoman-held peninsula on 25 April 1915. Last Allied withdrawals ended on 9 January 1916.',NAM,'war'),item('Armenian genocide, 1915–1916',1915,'kharput','USHMM describes massacres and lethal deportations across Ottoman provinces. Its overview gives a death estimate of at least 664,000 and possibly 1.2 million. The point locates Kharput as a documented example, not all victims.',USHMM,'people'),item('Armistice of Mudros',19181030,'istanbul','The armistice was signed on 30 October 1918. This marker locates the Ottoman capital affected by the settlement, not the signing site.',TBMM),item('Assembly opens in Ankara',19200423,'ankara','The new assembly opened in Ankara on 23 April 1920.',TBMM),item('Sultanate abolished',19221101,'ankara','The assembly abolished the sultanate on 1 November 1922.',MEB)]
republic=[item('Compulsory exchange convention',19230130,'lausanne','The convention prescribed transfers by nationality and religion and exempted specified Constantinople Greeks and Western Thrace Muslims.',EXCHANGE,'people'),item('Treaty of Lausanne signed',19230724,'lausanne','The peace treaty was signed on 24 July 1923. Its border provisions left the Iraq frontier for later settlement.',TREATY),item('Ankara becomes the capital',19231013,'ankara','Ankara became the government centre on 13 October 1923.',MEB),item('Republic proclaimed',19231029,'ankara','The republic was proclaimed on 29 October 1923.',MEB),item('Caliphate abolished',19240303,'ankara','The caliphate was abolished on 3 March 1924.',MEB),item('New alphabet law',19281101,'ankara','The assembly adopted the new Turkish letters law on 1 November 1928.',MEB)]
republic = [item('Samsun: national struggle',19190519,'samsun','Mustafa Kemal arrived in Samsun on 19 May 1919.',MEB,'war'),item('Sakarya campaign',19210823,'sakarya','The Sakarya battle began on 23 August 1921. This point is an approximate campaign-region locator, not a mapped front.',MEB,'war'),item('Dumlupınar campaign',19220830,'dumlupinar','The decisive battle in the August offensive took place on 30 August 1922. Location is schematic.',MEB,'war'),item('Turkish forces enter Smyrna',19220909,'izmir','Turkish forces entered Smyrna (İzmir today) on 9 September 1922.',MEB,'war')] + republic
for name,items in [('reform',reform),('war',war),('republic',republic)]:
 write(OUT/(name+'.json'),{'source':'editorial','asOf':'1928-11-01' if name=='republic' else ('1922-11-01' if name=='war' else '1908-07-23'),'retrieved':'2026-10-14','note':'Facts paraphrased and compiled by Orbis, with a source URL on every event. Locations are approximate city/region locators, not surveyed event or battle footprints. Textual factual references do not import source prose, photos or restricted datasets. Official national chronologies support dates, not every interpretation. Period labels are explanatory conventions, not official renaming dates.','kinds':{'politics':{'label':'Political event','color':'c1'},'war':{'label':'Military event','color':'muted'},'people':{'label':'People and displacement','color':'muted'}},'items':items,'places':[{'at':AT['istanbul'],'names':[{'name':'Constantinople (Istanbul today)','from':1800,'to':1929}]},{'at':AT['ankara'],'names':[{'name':'Ankara','from':1800,'to':1929}]}]})
def shapes(year='t'):return {'type':'shapes','data':'borders','year':year,'inner':False,'labels':False,'opacity':0.5}
def cards(window=None,kinds=None):
 d={'type':'cards','data':'events','year':'t','list':True,'labels':False}
 if window is not None:d['window']=window
 if kinds is not None:d['kinds']=kinds
 return d
def places(year=1923):return {'type':'places','data':'events','year':year}
def point(place,label):return {'at':AT[place],'label':label,'r':4,'color':'muted'}
def scene(title,text,center,zoom,layers,**kw):return {'title':title,'text':text,'view':{'mode':'globe','center':center,'zoom':zoom},'modernBorders':False,'layers':layers,**kw}
notes='Geometry: https://icr.ethz.ch/data/cshapes/ , CShapes 2.0 (Schvitz et al. 2022), CC BY-NC-SA 4.0. Dates: 1886-01-01, 1900-07-01, 1914-07-01, 1920-01-01, 1925-01-01. Shapes are legal-state snapshots, not occupation/front lines; dependencies and small changes are omitted. Orbis subsets remain CC BY-NC-SA. Event text is original factual annotation with citations; city/region locations are approximate locators. Dates are displayed in Gregorian form. '
chapters=[
('tr-empire-pressure','An empire under pressure','Constitutions, interrupted parliamentary rule and the changing geography of the late Ottoman state.','reform',notes+'Constitution articles 7, 8, 11, 17: '+CONSTITUTION+' . Parliamentary dates and restoration: '+TBMM+' .',[
 scene('An empire beyond Anatolia','This is the Ottoman state as mapped on 1 January 1886. Its shape reaches beyond Anatolia into southeastern Europe and the Arab provinces. It is a legal-border snapshot, not a map of every community, dependency or degree of imperial authority.',[34,37],3.5,[shapes(1886)],points=[point('istanbul','Constantinople (Istanbul today)'),point('thessaloniki','Salonika (Thessaloniki today)')]),
 scene('What did Ottoman mean?','The 1876 constitution called the empire’s subjects Ottomans regardless of religion. It also made Islam the state religion and preserved substantial powers for the sultan. Those legal promises help explain the ambition of reform; they do not establish that every community experienced equal treatment.',[29,41],8,[places('t'),cards()],timeline={'years':[18761223,18770319,18780214],'format':'date','start':18761223}),
 scene('A parliament, briefly','Parliament opened in March 1877, then was adjourned indefinitely in February 1878. Follow the dated cards in the imperial capital. A constitution and a parliament did not by themselves make the sultan answerable to an enduring elected legislature.',[29,41],7,[places('t'),cards()],timeline={'years':[18761223,18770319,18780214],'format':'date','start':18780214}),
 scene('The constitution returns','In July 1908, officers and troops associated with the constitutional movement forced the restoration of the constitution. Macedonia was a centre of the revolt; the marked Salonika locates that setting. The map’s borders are the earlier 1900 snapshot, not a newly invented 1908 boundary.',[27,41],5,[shapes(19000701),cards(),places('t')],timeline={'years':[19080723],'format':'date','start':19080723}),
 scene('The state contracts','Compare three observations: 1 January 1886, 1 July 1900 and 1 July 1914. The Ottoman state loses much of its European extent while retaining Anatolia and territories farther south. These are selected legal snapshots held between observations, not a continuous reconstruction of every treaty or battle.',[33,37],3.5,[shapes()],timeline={'years':[1886,1900,1914],'start':1886,'captions':{'1886':'Snapshot: 1 January 1886','1900':'Snapshot: 1 July 1900','1914':'Snapshot: 1 July 1914'}})
]),
('tr-war-dissolution','War and dissolution','Gallipoli, the Armenian genocide and the political rupture between the imperial capital and Ankara.','war',notes+'Gallipoli: '+NAM+' . Armenian genocide and death-estimate range: '+USHMM+' . Armistice and assembly: '+TBMM+' . Abolition: '+MEB+' .',[
 scene('The state before the war','The shaded territory is the Ottoman legal-state snapshot of 1 July 1914. The war brought fighting on several fronts, but a border dataset cannot tell us who occupied each place each month. The following scenes use located events rather than invented moving control areas.',[36,36],3.5,[shapes(1914)],points=[point('gallipoli','Dardanelles')]),
 scene('The Dardanelles','Allied troops landed on the Gallipoli peninsula on 25 April 1915. Ottoman defenders prevented a breakthrough; the last Allied evacuation ended on 9 January 1916. The straits explain why this small peninsula mattered. The marker shows the campaign region, not a landing beach or a front line.',[26.4,40.25],12,[cards(kinds=['war'])],timeline={'years':[19150425,19150810,19160109],'format':'date','start':19150425}),
 scene('The Armenian genocide','In 1915–1916, Ottoman authorities carried out massacres and deportations that destroyed Armenian communities. USHMM estimates at least 664,000 deaths and possibly 1.2 million. The marked Kharput and Syrian desert are documented places in that history, not a complete map of killings or a numerical distribution of victims.',[39,37],5,[],points=[point('kharput','Kharput (near Elazığ today)'),point('syria','Syrian desert region')]),
 scene('Two political centres','The Armistice of Mudros was signed in October 1918. After the occupation of Constantinople and dissolution of its parliament, a new assembly opened in Ankara in April 1920. The two marked cities make the rupture visible; the map does not assign either government invented zones of control.',[31,40],6,[cards(kinds=['politics']),places('t')],timeline={'years':[19181030,19200423],'format':'date','start':19200423}),
 scene('The dynasty loses sovereignty','On 1 November 1922, the Ankara assembly abolished the sultanate. A political institution ended before the republic was formally proclaimed. The dated card locates the decision; the earlier border snapshots cannot stand in for the military and diplomatic settlement that followed.',[32.85,39.93],7,[cards(kinds=['politics'])],timeline={'years':[19221101],'format':'date','start':19221101})
]),
('tr-republic','Making the republic','Treaty borders, compulsory population exchange and a new political centre in Ankara.','republic',notes+'Treaty, especially articles 2–4 and 37–45: '+TREATY+' . Exchange convention articles 1–3: '+EXCHANGE+' . Capital, proclamation, caliphate and alphabet dates: '+MEB+' .',[
 scene('Another war after the armistice','The national struggle of 1919–1922 fought over the future of Anatolia. Greek and Turkish forces confronted each other across western Anatolia: Sakarya in 1921, Dumlupınar and the Turkish entry into Smyrna (İzmir today) in 1922. The dated cards locate selected turning points, not continuous fronts or an exhaustive account of the war.',[31,39],5,[cards(kinds=['war'])],timeline={'years':[19190519,19210823,19220830,19220909],'format':'date','start':19190519}),
 scene('Peace, with unfinished borders','The Treaty of Lausanne was signed on 24 July 1923. It set out the Greek and Bulgarian frontiers and provisions concerning Syria, but left the Iraq frontier for later settlement. The shaded map is a 1 January 1925 observation, not a claim that every border question was settled at Lausanne.',[35,38],4,[shapes(1925)],points=[point('lausanne','Lausanne')]),
 scene('People required to move','The January 1923 convention prescribed compulsory transfers of Turkish nationals of Greek Orthodox religion and Greek nationals of Muslim religion. Specified Greeks of Constantinople and Muslims of Western Thrace were exempt. The marked places locate the specified exemptions; they are not deportation routes or measures of the numbers displaced.',[27,39],5,[],points=[point('istanbul','Constantinople: specified exemption'),{'at':[25.3,41.1],'label':'Western Thrace: specified exemption','r':4,'color':'muted'}],legend=[{'color':'muted','label':'Places named in the convention; no transfer routes shown'}]),
 scene('An inland capital','Ankara became the government centre on 13 October 1923. The republic was proclaimed there on 29 October. Compare its inland position with Constantinople on the straits. Tap the cards for the dates; the change in capital was a political choice, not the movement of a population centre.',[31,40.4],6,[cards(kinds=['politics','people']),places('t')],timeline={'years':[19231013,19231029],'format':'date','start':19231013}),
 scene('Changing institutions','The republic’s proclamation did not finish its institutional transformation. The caliphate was abolished in March 1924; the new Turkish alphabet law followed in November 1928. These cards locate national decisions in Ankara. They do not imply that every region adopted reforms at the same pace.',[32.85,39.93],6,[cards(kinds=['politics'])],timeline={'years':[19240303,19281101],'format':'date','start':19240303}),
 scene('A state, not a complete identity map','The 1925 snapshot outlines the state, not the languages, faiths or identities of everyone inside it. Lausanne also prescribed minority protections. Read the border and population-transfer scenes together: territorial settlement and the lives of communities are different parts of the making of the republic.',[35,39],4,[shapes(1925),places(1925)],points=[point('istanbul','Istanbul'),point('ankara','Ankara')])
])]
for sid,title,hook,eventfile,note,scenes in chapters:
 write(ROOT/f'stories/{sid}.json',{'id':sid,'cat':'People','title':title,'hook':hook,'notes':note,'sources':['editorial','cshapes'],'data':{'events':f'data/history/turkey/{eventfile}.json','borders':'data/history/turkey/snapshots.json'},'scenes':scenes})
print('Built',len(chapters),'unlisted Turkey chapters and',len(geoms),'dated source geometries')
